    index += 2

    splits = defaultdict(list)
    for _ in range(m):
        mi = int(input[index])
        li = int(input[index + 1])
        index += 2
        rule = []
        for _ in range(li):
            x = int(input[index])
            index += 1
            rule.append(x)
        splits[mi].append(rule)

    INF = float('inf')
    MAX_DIAMONDS = 314000000

    def dfs(monster, memo):
        if monster in memo:
            return memo[monster]
        min_diamonds = INF
        max_diamonds = -INF
        for rule in splits[monster]:
            min_current = 0
            max_current = 0
            for x in rule:
                if x == -1:
                    min_current += 1
                    max_current += 1
                else:
                    min_child, max_child = dfs(x, memo)
                    if min_child == -1:
                        min_current = -1
                    elif min_current != -1:
                        min_current += min_child
                    if max_child == -2:
                        max_current = -2
                    elif max_current != -2:
                        max_current += max_child
            if min_current != -1:
                min_diamonds = min(min_diamonds, min_current)
            if max_current != -2:
                max_diamonds = max(max_diamonds, max_current)
        if min_diamonds == INF:
            min_diamonds = -1
        if max_diamonds == -INF:
            max_diamonds = -1
        if min_diamonds > MAX_DIAMONDS:
            min_diamonds = MAX_DIAMONDS
        if max_diamonds > MAX_DIAMONDS:
            max_diamonds = MAX_DIAMONDS
        memo[monster] = (min_diamonds, max_diamonds)
        return min_diamonds, max_diamonds

    memo = {}
    results = []
    for i in range(1, n + 1):
        min_diamonds, max_diamonds = dfs(i, memo)
        results.append((min_diamonds, max_diamonds))

    for min_diamonds, max_diamonds in results:
